FOR w IN SELECT s.id, s.main_workout, x.ks FROM public.smarty_workouts s JOIN _w x ON x.id = s.id LOOP
  m := w.main_workout; a := strpos(m, 'Main Workout'); c := a - 1 + strpos(substr(m, a), 'Cool Down'); mid := substr(m, a, c - a);
  FOREACH kk IN ARRAY w.ks LOOP SELECT _p.o INTO o FROM _p WHERE _p.k = kk; mid := replace(mid, o, '@@' || kk || '@@'); END LOOP;
  FOREACH kk IN ARRAY w.ks LOOP SELECT _p.n INTO n FROM _p WHERE _p.k = kk; mid := replace(mid, '@@' || kk || '@@', n); END LOOP;
  UPDATE public.smarty_workouts SET main_workout = left(m, a - 1) || mid || substr(m, c), updated_at = now() WHERE id = w.id;
END LOOP;
END $do$;
UPDATE public.workouts w SET main_workout = s.main_workout, updated_at = now() FROM public.smarty_workouts s, public.smarty_workouts_backup_conditioning_20261004 b WHERE w.created_by = 'smarty:' || s.id::text AND b.id = s.id AND w.main_workout = b.main_workout AND s.main_workout <> b.main_workout AND w.status = 'created' AND w.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM public.set_logs l WHERE l.workout_id = w.id);